<?php

declare(strict_types=1);

namespace Identity\Application\Command\SecondFactor;

use Shared\Application\Audit\AuditableCommand;
use Shared\Application\Audit\AuditAction;
use Shared\Application\Audit\AuditContext;
use Shared\Application\Audit\Target;
use Shared\Application\Security\RevealsSecret;

/**
 * Replaces the backup codes with a new set generated by the UI and shown once.
 */
final readonly class RegenerateBackupCodes implements AuditableCommand, RevealsSecret
{
    /**
     * @param list<string> $backupCodes
     */
    public function __construct(
        public string $userId,
        #[\SensitiveParameter] public array $backupCodes,
    ) {
    }

    public function auditAction(): AuditAction
    {
        return AuditAction::named('identity.regenerate_backup_codes');
    }

    public function auditTarget(): Target
    {
        return Target::of('user', $this->userId);
    }

    public function auditContext(): AuditContext
    {
        return AuditContext::empty();
    }
}
